from pathlib import Path
import re
path = Path('/home/ubuntu/stargatewars/game.php')
text = path.read_text()
replacement = r'''function planetListPage(){const p=state.planet_list||{},d=state.planet_defenses||{},colonies=p.colonies||[],defenses=d.planets||[],csrf=state.csrf||'',u=(state.universe_planets||{}).planets||[],planetOptions=u.map(x=>`<option value="${fmt(x.id||x.planet_id)}">${esc(x.name||x.planet_name||('Planet #'+(x.id||x.planet_id)))}</option>`).join('');const colonyRows=colonies.map(c=>`<div class="row"><div><strong>${esc(c.colony_name||c.planet_name||'Colony')}</strong><small>${esc(c.coordinate_label||'Unknown coordinate')} · ${esc(c.planet_class||'world')} · ${esc(c.biome||'unknown biome')}</small></div><div><span class="badge ${c.life_support_state==='stable'?'good':''}">${esc(c.life_support_state||'unknown')}</span><strong>${fmt(c.production_output||0)} output</strong></div><span class="badge">COLONY #${fmt(c.id)}</span></div>`).join('');const defenseRows=defenses.map(x=>`<div class="row"><div><strong>${esc(x.planet_name||('Planet #'+x.planet_id))}</strong><small>Rating ${fmt(x.defense_rating||0)} · Shield ${fmt(x.shield_integrity||0)} · Garrison ${fmt(x.garrison_units||0)}</small></div><span class="badge">${fmt(x.structures||0)} structures</span><form method="post" action="actions/game.php" class="inline-form">${csrf}<input type="hidden" name="action" value="planet_defense"><input type="hidden" name="redirect" value="planets"><input type="hidden" name="planet_id" value="${fmt(x.planet_id)}"><input type="hidden" name="defense_type" value="planetary_shield"><button class="button" type="submit">Upgrade defense</button></form></div>`).join('');document.getElementById('section').textContent='PLANETS';document.getElementById('title').textContent='Planet List';document.getElementById('description').textContent='Planet List — '+(p.formula||'colony output = base production × biome × race × government × morale');document.getElementById('content').innerHTML=`<div class="cc-grid"><div class="card wide"><div class="eyebrow">OWNED COLONIES</div><h2>Colony production and life support</h2>${colonyRows||'<div class="empty"><strong>No colonies found.</strong><p>Explore the universe and establish your first colony.</p></div>'}</div><div class="card side-card"><div class="eyebrow">EXPLORE</div><h2>Survey a world</h2><form method="post" action="actions/game.php" class="action-form">${csrf}<input type="hidden" name="action" value="explore"><input type="hidden" name="redirect" value="planets"><label>World name<input name="name" maxlength="100" required placeholder="Asteria Prime"></label><label>Planet type<input name="planet_type" maxlength="60" required value="temperate"></label><button class="button" type="submit">Explore</button></form><p class="permission">Exploration validates resource cost, cooldown, and discovery persistence on the server.</p></div><div class="card side-card"><div class="eyebrow">COLONIZE</div><h2>Establish a colony</h2><form method="post" action="actions/game.php" class="action-form">${csrf}<input type="hidden" name="action" value="colonize_planet"><input type="hidden" name="redirect" value="planets"><label>Planet<select name="planet_id" required><option value="">Select discovered planet</option>${planetOptions}</select></label><label>Colony name<input name="colony_name" maxlength="120" required placeholder="New Frontier"></label><button class="button dark" type="submit">Colonize</button></form><p class="permission">Habitability, occupancy, colony limit, resources, cooldown, and transaction state are validated atomically.</p></div><div class="card wide"><div class="eyebrow">PLANET DEFENSES</div><h2>Defense grid and shield integrity</h2>${defenseRows||'<div class="empty">No defense records are available yet.</div>'}</div><div class="card wide"><div class="eyebrow">LIFE-SUPPORT STATUS</div><h2>Food, water, morale, and fleet presence</h2>${colonies.map(c=>`<div class="row"><span>${esc(c.colony_name||c.planet_name||'Colony')}</span><span>Food ${fmt((c.food_ratio||0)*100)}% · Water ${fmt((c.water_ratio||0)*100)}% · Morale ${Number(c.morale||0).toFixed(2)} · Fleet ${fmt(c.fleet_presence||0)}</span></div>`).join('')||'<div class="empty">Colony telemetry will appear after colonization.</div>'}</div><div class="card wide"><div class="eyebrow">SERVER CONTRACT</div><h2>Planet action safeguards</h2><p class="permission">Explore, Colonize, and Upgrade Defense are authenticated, CSRF-protected, ownership-scoped, cooldown-checked, resource-validated, and transactional. The browser sends only commander intent.</p>${['ready','empty','protected','success','error'].map(s=>`<div class="row"><span>${s}</span><span class="badge">HANDLED</span></div>`).join('')}</div></div>`}function genericPage(){'''
new_text, count = re.subn(r'function planetListPage\(\)\{.*?function genericPage\(\)\{', replacement, text, count=1, flags=re.S)
if count != 1:
    raise SystemExit('Planet List function boundary not found')
path.write_text(new_text)
print('replaced Planet List renderer')
